#include "../original-tcpe/src/network/java/JavaTitleState.h"
#include <cassert>
#include <iostream>
#include <limits>
int main(){JavaTitleState s;assert(s.duration()==100&&s.alpha()==0);s.subtitle="Before title";s.setTitle("Fight!");assert(s.remaining==100&&s.subtitle=="Before title"&&s.alpha()==0);for(int i=0;i<5;++i)s.tick();assert(s.alpha()==127);for(int i=0;i<5;++i)s.tick();assert(s.alpha()==255);s.subtitle="Changed";assert(s.remaining==90);s.setTimes(-1,5,-1);assert(s.fadeIn==10&&s.stay==5&&s.fadeOut==20&&s.remaining==35);for(int i=0;i<25;++i)s.tick();assert(s.alpha()==127);for(int i=0;i<10;++i)s.tick();assert(s.remaining==0&&!s.hasTitle&&s.title.empty()&&s.subtitle.empty());s.setTimes(0,10,0);s.subtitle="Visible with empty title";s.setTitle("");assert(s.hasTitle&&s.alpha()==255);s.clear(false);assert(s.fadeIn==0&&s.stay==10&&s.fadeOut==0&&!s.hasTitle);s.clear(true);assert(s.duration()==100);s.setTimes(std::numeric_limits<int>::max(),std::numeric_limits<int>::max(),std::numeric_limits<int>::max());s.setTitle("Long");assert(s.remaining==int64_t(std::numeric_limits<int>::max())*3);std::cout<<"Title timing: fade in/stay/fade out, subtitle ordering, negative retention, empty title, clear/reset and safe duration PASS\n";}
